#define main legacy_main
#include "../tensorAccessor-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <algorithm>
struct Fixture{int64_t nr,nc,rs,cs,vs,os;std::vector<float>m,v,pm,pv;std::vector<double>gold;float*dm,*dv,*dpm,*dpv,*dr,*dpr;Fixture(int which){nr=which==1?257:which==2?513:129;nc=which==1?131:which==2?257:65;rs=which==3?137:nc;cs=which==3?2:1;vs=which==3?3:1;os=which==3?2:1;m.resize(nr*nc);v.resize(nc);if(which==1){srand(123);for(auto&x:m)x=rand()/(float)RAND_MAX;for(auto&x:v)x=rand()/(float)RAND_MAX;}else{for(int64_t i=0;i<nr;i++)for(int64_t j=0;j<nc;j++)m[i*nc+j]=which==2?float((i*17+j*13)%65-32)/16.f:float((i*31+j*7)%97-48)/8.f;for(int64_t j=0;j<nc;j++)v[j]=which==2?float((j%2?-1:1)*(j%9+1))/8.f:float((j*5)%17-8)/4.f;}pm.assign(nr*rs,-123.25f);pv.assign(nc*vs,-123.25f);for(int64_t i=0;i<nr;i++)for(int64_t j=0;j<nc;j++)pm[i*rs+j*cs]=m[i*nc+j];for(int64_t j=0;j<nc;j++)pv[j*vs]=v[j];for(int64_t i=0;i<nr;i++){double sum=0;for(int64_t j=0;j<nc;j++)sum+=double(m[i*nc+j])*double(v[j]);gold.push_back(sum);}cudaMalloc(&dm,m.size()*4);cudaMalloc(&dv,v.size()*4);cudaMemcpy(dm,m.data(),m.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dv,v.data(),v.size()*4,cudaMemcpyHostToDevice);if(rs==nc&&cs==1)dpm=dm;else{cudaMalloc(&dpm,pm.size()*4);cudaMemcpy(dpm,pm.data(),pm.size()*4,cudaMemcpyHostToDevice);}if(vs==1)dpv=dv;else{cudaMalloc(&dpv,pv.size()*4);cudaMemcpy(dpv,pv.data(),pv.size()*4,cudaMemcpyHostToDevice);}cudaMalloc(&dr,nr*4);cudaMalloc(&dpr,nr*os*4);}void reset(){std::vector<float>a(nr*os,-123.25f);cudaMemcpy(dr,a.data(),nr*4,cudaMemcpyHostToDevice);cudaMemcpy(dpr,a.data(),nr*os*4,cudaMemcpyHostToDevice);}void launch(int mode){if(mode==0)raw_accessor_kernel<<<(nr+255)/256,256>>>(nr,nc,dr,dm,dv);else{int64_t ms[2]={nr,nc},mt[2]={rs,cs};PackedTensorAccessor64<float,1,RestrictPtrTraits>ra(dpr,&nr,&os),va(dpv,&nc,&vs);PackedTensorAccessor64<float,2,RestrictPtrTraits>ma(dpm,ms,mt);tensor_packed_accessor_kernel<<<(nr+255)/256,256>>>(ra,ma,va);}}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;std::vector<Fixture>fs;for(int i=1;i<=3;i++)fs.emplace_back(i);printf("PACKED_DEVICE_ABI_BYTES %zu %zu %zu\n",sizeof(PackedTensorAccessor64<float,1,RestrictPtrTraits>),sizeof(PackedTensorAccessor64<float,2,RestrictPtrTraits>),sizeof(PackedTensorAccessor64<float,1,RestrictPtrTraits>));std::vector<float>prefix;for(auto&f:fs){float h[]={float(f.nr),float(f.nc),float(f.rs),float(f.cs),float(f.vs),float(f.os),float(f.pm.size()),float(f.pv.size()),float(f.nr*f.os),-123.25f};prefix.insert(prefix.end(),h,h+10);for(auto*p:{&f.m,&f.v,&f.pm,&f.pv})prefix.insert(prefix.end(),p->begin(),p->end());f.reset();f.launch(0);f.launch(1);}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){for(auto&f:fs)f.reset();cudaDeviceSynchronize();double times[6]={0};for(int i=0;i<3;i++)for(int mode=0;mode<2;mode++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)fs[i].launch(mode);cudaDeviceSynchronize();times[2*i+mode]=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;}bool ok=cudaGetLastError()==cudaSuccess;double ma=0,mr=0,elapsed=0;size_t guards=0;std::vector<float>got;for(auto&f:fs)for(int mode=0;mode<2;mode++){int64_t stride=mode==0?1:f.os;std::vector<float>a(f.nr*stride);cudaMemcpy(a.data(),mode==0?f.dr:f.dpr,a.size()*4,cudaMemcpyDeviceToHost);for(size_t i=0;i<a.size();i++)if(i%stride==0){double gold=f.gold[i/stride],err=fabs(double(a[i])-gold);ma=std::max(ma,err);mr=std::max(mr,err/std::max(fabs(gold),1e-12));ok&=std::isfinite(a[i])&&err<=1e-3;}else{guards++;ok&=a[i]==-123.25f;}got.insert(got.end(),a.begin(),a.end());}auto art=prefix;art.insert(art.end(),got.begin(),got.end());std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(file.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);for(auto t:times)elapsed+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"padding_guard_count\":%zu,\"timing_region\":\"sum6paths_raw_packed_Float32_matvec_kernelonly\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[",trial,elapsed,ok?"true":"false",got.size(),ma,mr,guards,rep);for(int i=0;i<6;i++)printf(i?",%.17g":"%.17g",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file.c_str(),art.size());if(!ok)return 2;}}
